import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from '@google/genai';
import { Patient } from '../types';
import { Send, Bot, User, Loader2, Sparkles, AlertTriangle } from 'lucide-react';
import Markdown from 'react-markdown';

interface AIAssistantProps {
  patient: Patient;
}

interface Message {
  id: string;
  role: 'user' | 'assistant';
  content: string;
}

export function AIAssistant({ patient }: AIAssistantProps) {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: '1',
      role: 'assistant',
      content: `Olá, Doutor(a). Sou o assistente de IA do Saúde ++. Estou analisando o prontuário de **${patient.name}**. Como posso ajudar na sua decisão clínica hoje?`
    }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  useEffect(() => {
    setMessages([
      {
        id: Date.now().toString(),
        role: 'assistant',
        content: `Olá, Doutor(a). Mudei para o prontuário de **${patient.name}**. Como posso ajudar?`
      }
    ]);
  }, [patient.id]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input.trim()
    };

    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.REACT_APP_GEMINI_API_KEY || '' });

      const systemInstruction = `
Você é um assistente médico de IA altamente qualificado integrado à plataforma "Saúde ++".
Seu objetivo é auxiliar médicos na análise de prontuários, sugerir hipóteses diagnósticas, alertar sobre interações medicamentosas e resumir históricos clínicos.
Você deve ser profissional, conciso, baseado em evidências e focado na segurança do paciente.
Sempre lembre o médico que suas sugestões não substituem o julgamento clínico humano.

Aqui estão os dados do paciente atual que o médico está visualizando:
Nome: ${patient.name}
Idade: ${patient.age}
Sexo: ${patient.gender}
Tipo Sanguíneo: ${patient.bloodType}
Alergias: ${patient.allergies.join(', ')}
Condições Crônicas: ${patient.conditions.join(', ')}
Medicamentos Atuais: ${patient.medications.join(', ')}
Últimos Exames: ${JSON.stringify(patient.labResults)}
Histórico de Consultas: ${JSON.stringify(patient.recentVisits)}
Notas Adicionais: ${patient.notes}

Responda às perguntas do médico com base EXCLUSIVAMENTE nestes dados e no seu conhecimento médico geral.
Seja direto e use formatação Markdown para facilitar a leitura (listas, negrito para destacar pontos críticos).
`;

      const history = messages.map(m => `${m.role === 'user' ? 'Médico' : 'Assistente'}: ${m.content}`).join('\n');
      const prompt = `Histórico da conversa:\n${history}\n\nMédico: ${userMessage.content}\nAssistente:`;

      const response = await ai.models.generateContent({
        model: 'gemini-1.5-pro',
        contents: prompt,
        config: {
          systemInstruction,
          temperature: 0.2
        }
      });

      const assistantMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response.text || 'Desculpe, não consegui gerar uma resposta.'
      };

      setMessages(prev => [...prev, assistantMessage]);
    } catch (error) {
      console.error('Error calling Gemini:', error);
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'assistant',
        content: 'Ocorreu um erro ao processar sua solicitação. Verifique sua conexão ou a chave da API.'
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const quickPrompts = [
    'Resuma o histórico clínico',
    'Há interações medicamentosas?',
    'Analise os últimos exames',
    'Sugira conduta para a próxima consulta'
  ];

  return (
    <div className="flex h-full flex-col bg-white border-l border-gray-200">
      <div className="flex items-center justify-between border-b border-gray-200 bg-indigo-50 px-6 py-4">
        <div className="flex items-center space-x-3">
          <div className="flex h-10 w-10 items-center justify-center rounded-full bg-indigo-100 text-indigo-600">
            <Sparkles className="h-5 w-5" />
          </div>
          <div>
            <h2 className="text-lg font-semibold text-gray-900">Saúde ++ Copilot</h2>
            <p className="text-xs text-indigo-600 font-medium">Assistente Clínico IA</p>
          </div>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-6">
        <div className="rounded-lg bg-amber-50 p-3 text-xs text-amber-800 flex items-start border border-amber-200">
          <AlertTriangle className="h-4 w-4 mr-2 flex-shrink-0 mt-0.5" />
          <p>As sugestões da IA são apenas para suporte à decisão clínica e não substituem o julgamento profissional do médico.</p>
        </div>

        {messages.map((msg) => (
          <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`flex max-w-[85%] ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
              <div className={`flex h-8 w-8 flex-shrink-0 items-center justify-center rounded-full ${
                msg.role === 'user' ? 'ml-3 bg-gray-100 text-gray-600' : 'mr-3 bg-indigo-100 text-indigo-600'
              }`}>
                {msg.role === 'user' ? <User className="h-4 w-4" /> : <Bot className="h-4 w-4" />}
              </div>
              <div className={`rounded-2xl px-4 py-3 text-sm ${
                msg.role === 'user'
                  ? 'bg-gray-900 text-white rounded-tr-none'
                  : 'bg-gray-100 text-gray-800 rounded-tl-none'
              }`}>
                {msg.role === 'user' ? (
                  <p className="whitespace-pre-wrap">{msg.content}</p>
                ) : (
                  <div className="prose prose-sm max-w-none prose-p:leading-relaxed prose-pre:bg-gray-800 prose-pre:text-gray-100">
                    <Markdown>{msg.content}</Markdown>
                  </div>
                )}
              </div>
            </div>
          </div>
        ))}

        {isLoading && (
          <div className="flex justify-start">
            <div className="flex max-w-[85%] flex-row">
              <div className="mr-3 flex h-8 w-8 flex-shrink-0 items-center justify-center rounded-full bg-indigo-100 text-indigo-600">
                <Bot className="h-4 w-4" />
              </div>
              <div className="flex items-center rounded-2xl rounded-tl-none bg-gray-100 px-4 py-3 text-sm text-gray-800">
                <Loader2 className="h-4 w-4 animate-spin text-indigo-600 mr-2" />
                Analisando prontuário...
              </div>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <div className="border-t border-gray-200 p-4">
        <div className="mb-3 flex flex-wrap gap-2">
          {quickPrompts.map((prompt, idx) => (
            <button
              key={idx}
              onClick={() => setInput(prompt)}
              className="rounded-full border border-gray-200 bg-white px-3 py-1 text-xs font-medium text-gray-600 transition-colors hover:bg-gray-50 hover:text-indigo-600"
            >
              {prompt}
            </button>
          ))}
        </div>
        <div className="relative flex items-end rounded-xl border border-gray-300 bg-white shadow-sm focus-within:border-indigo-500 focus-within:ring-1 focus-within:ring-indigo-500">
          <textarea
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Faça uma pergunta sobre o paciente..."
            className="max-h-32 min-h-[52px] w-full resize-none rounded-xl border-0 bg-transparent py-3.5 pl-4 pr-12 text-sm text-gray-900 focus:ring-0"
            rows={1}
          />
          <button
            onClick={handleSend}
            disabled={!input.trim() || isLoading}
            className="absolute bottom-2 right-2 flex h-9 w-9 items-center justify-center rounded-lg bg-indigo-600 text-white transition-colors hover:bg-indigo-700 disabled:bg-gray-300"
          >
            <Send className="h-4 w-4" />
          </button>
        </div>
        <p className="mt-2 text-center text-[10px] text-gray-400">
          A IA pode cometer erros. Verifique informações importantes.
        </p>
      </div>
    </div>
  );
}
